# D40 · Part 0~4 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d40_flow.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   목소리 데이터 거르기 → 글자 정규화와 토큰 → 단조 정렬 → 다섯 손실 → 걸음 수와 과적합 → 평가 → 워터마크를 장난감 모델로 한 번에


import math
import re

import numpy as np

SR = 16000                                   # 표본화율 (16 kHz)
HOP = 320                                    # 20 ms마다 한 번 잼


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def frame_db(y: np.ndarray) -> np.ndarray:
    """20 ms마다 (조각 길이 40 ms) 소리 크기 dB."""
    n = (len(y) - 640) // HOP + 1
    fr = np.stack([y[i * HOP:i * HOP + 640] for i in range(n)])
    return 20 * np.log10(np.sqrt((fr ** 2).mean(1)) + 1e-9)


def burst(n_syl: int, f0: float, amp: float = 0.3, jitter: float = 0.0, seed: int = 0) -> np.ndarray:
    """[대체] TTS 대신 합성 목소리: 음절 n_syl개(0.18초, 앞 85%가 소리). jitter는 높낮이가 떨리는 정도, 음절마다 배음 2개."""
    rng = np.random.default_rng(seed)
    L = int(0.18 * SR)
    t = np.arange(int(L * 0.85)) / SR
    out = []
    for i in range(n_syl):
        f = f0 * (1 + jitter * rng.standard_normal())
        y = np.sin(2 * np.pi * f * t) + 0.4 * np.sin(2 * np.pi * 2 * f * t)
        out += [amp * y / 1.4 * np.hanning(len(t)), np.zeros(L - len(t))]
    return np.concatenate(out).astype(np.float32)


def _part_dataq():
    # ── Part 1 · 목소리 데이터 준비: TTS 데이터의 기준 ──
    TARGET_DB = -23.0                            # 학습용 음량(RMS, dBFS)


    def quality(y: np.ndarray) -> tuple:
        """(SNR dB, 깨진 표본의 비율): 큰 조각의 전력과 가장 조용한 10% 조각의 전력을 비교."""
        db = frame_db(y)
        p = 10 ** (db / 10)
        return float(10 * np.log10(p[db > np.median(db)].mean() / np.sort(p)[:max(1, len(p) // 10)].mean())), float(np.mean(np.abs(y) >= 0.999))


    def prep_wav(y: np.ndarray, top_db: float = 35.0, pad: float = 0.1) -> np.ndarray:
        """앞뒤 침묵(가장 큰 곳보다 top_db 넘게 작은 곳)을 pad만 남기고 자르고, RMS를 TARGET_DB로 맞춘다."""
        idx = np.where(frame_db(y) > frame_db(y).max() - top_db)[0]
        a, b = max(0, idx[0] * HOP - int(pad * SR)), min(len(y), idx[-1] * HOP + 640 + int(pad * SR))
        y = y[a:b]
        return np.clip(y * 10 ** (TARGET_DB / 20) / np.sqrt(np.mean(y ** 2)), -1, 1).astype(np.float32)


    def make_utt(kind: str, seed: int) -> np.ndarray:
        rng = np.random.default_rng(seed)
        quiet = lambda s: 10 ** (-60 / 20) * rng.standard_normal(int(s * SR))              # 조용한 방 잡음 -60 dB
        if kind == "clipped":
            y = np.clip(burst(12, 150, 3.0, seed=seed), -1, 1)                            # 입력이 너무 커서 깨짐
        elif kind == "short":
            y = burst(2, 150, seed=seed)                                                  # 0.36초: 너무 짧음
        elif kind == "longlead":
            y = np.r_[np.zeros(int(2.5 * SR)), burst(12, 150, seed=seed)]                 # 앞에 2.5초 침묵
        else:
            y = burst(12, 150, seed=seed)
        y = np.r_[quiet(0.4), y, quiet(0.4)] + (10 ** (-22 / 20) * rng.standard_normal(len(y) + int(0.8 * SR)) if kind == "noisy" else 0)
        return y.astype(np.float32)


    KINDS = ["good"] * 7 + ["clipped", "noisy", "short", "longlead"]
    rows = []
    for i, kind in enumerate(KINDS):
        raw = make_utt(kind, i)
        snr, clip = quality(raw)
        y = prep_wav(raw)
        sec = len(y) / SR
        ok = clip < 0.001 and snr >= 25 and 1.0 <= sec <= 12
        rows.append({"kind": kind, "snr": snr, "clip": clip, "sec": sec, "ok": ok, "rms": float(20 * np.log10(np.sqrt(np.mean(y ** 2)))), "lead": int(np.argmax(np.abs(y) > 0.01)) / SR})
        print(f"{kind:>9}: SNR {snr:5.1f} dB · 깨진 표본 {clip:.2%} · 길이 {sec:4.1f}초 → {'사용' if ok else '버림'}")
    kept = [r["kind"] for r in rows if r["ok"]]
    check(kept.count("good") == 7 and "longlead" in kept and not {"clipped", "noisy", "short"} & set(kept)
          and all(abs(r["rms"] - TARGET_DB) < 0.1 for r in rows if r["kind"] != "clipped") and all(r["lead"] < 0.3 for r in rows if r["ok"]),
          "깨진 소리 · 잡음 · 너무 짧은 녹음은 버리고, 앞 침묵은 잘라내며 음량은 -23 dB로 맞춰져야 해요.")


def _part_text():
    # ── Part 1-3 · 글자를 소리 나는 대로: 정규화 → 토큰 ──
    SINO = "영일이삼사오육칠팔구"
    NATIVE = {1: "한", 2: "두", 3: "세", 4: "네", 5: "다섯", 6: "여섯", 7: "일곱", 8: "여덟", 9: "아홉"}
    TENS = {1: "열", 2: "스물", 3: "서른", 4: "마흔", 5: "쉰", 6: "예순", 7: "일흔", 8: "여든", 9: "아흔"}
    NATIVE_UNITS = "시|개|명|살|잔|달|번"             # 고유어(하나 둘 셋)로 읽는 단위


    def read_number(n: int) -> str:
        """0 ~ 9999를 한자어로: 천 · 백 · 십 앞의 1은 읽지 않는다(123 → 백이십삼)."""
        if n == 0:
            return "영"
        out = ""
        for div, unit in ((1000, "천"), (100, "백"), (10, "십")):
            d, n = divmod(n, div)
            if d:
                out += ("" if d == 1 else SINO[d]) + unit
        return out + (SINO[n] if n else "")


    def read_big(n: int) -> str:
        """만 단위 이상: 네 자리씩 끊어 읽는다(15000 → 만 오천)."""
        q, r = divmod(n, 10000)
        if q == 0:
            return read_number(r)
        return ("만" if q == 1 else read_number(q) + "만") + (" " + read_number(r) if r else "")


    def read_native(n: int) -> str:
        """1 ~ 99를 고유어로(세 · 두 · 열두 · 스무)."""
        if n == 20:
            return "스무"
        t, u = divmod(n, 10)
        return (TENS[t] if t else "") + (NATIVE[u] if u else "")


    def normalize_text(text: str) -> str:
        text = re.sub(rf"(\d+)({NATIVE_UNITS})", lambda m: (read_native(int(m[1])) if 0 < int(m[1]) < 100 else read_big(int(m[1]))) + " " + m[2], text)
        return re.sub(r"(\d+)([가-힣]?)", lambda m: read_big(int(m[1])) + (" " + m[2] if m[2] else ""), text)


    def to_ids(text: str) -> list:
        """한글 → 초성(0~18) · 중성(19~39) · 종성(40~66) 토큰, 공백은 99. 유니코드 계산만으로 쪼갠다."""
        out = []
        for c in text:
            if "가" <= c <= "힣":
                code = ord(c) - 0xAC00
                out += [code // 588, 19 + code % 588 // 28] + ([40 + code % 28 - 1] if code % 28 else [])
            else:
                out.append(99)
        return out


    def from_ids(ids: list) -> str:
        out, i = "", 0
        while i < len(ids):
            if ids[i] == 99:
                out, i = out + " ", i + 1
                continue
            code = ids[i] * 588 + (ids[i + 1] - 19) * 28
            i += 2
            if i < len(ids) and 40 <= ids[i] <= 66:
                code, i = code + ids[i] - 40 + 1, i + 1
            out += chr(0xAC00 + code)
        return out


    raw = "오후 3시 30분에 2명 예약, 비용 15000원"
    norm = normalize_text(raw)
    print(raw, "→", norm)
    ids = to_ids("한글 말해요")
    print("토큰:", ids, "→ 되돌리기:", from_ids(ids))
    check([read_number(n) for n in (0, 10, 11, 123, 1000, 2024, 9999)] == ["영", "십", "십일", "백이십삼", "천", "이천이십사", "구천구백구십구"]
          and [read_native(n) for n in (3, 12, 20, 21)] == ["세", "열두", "스무", "스물한"]
          and norm == "오후 세 시 삼십 분에 두 명 예약, 비용 만 오천 원" and to_ids("한글") == [18, 19, 43, 0, 37, 47] and from_ids(ids) == "한글 말해요",
          "123 → 백이십삼, 3시 → 세 시, 15000 → 만 오천, 한 → [18, 19, 43]이어야 해요.")


def _part_mas():
    # ── Part 2 · 단조 정렬(Monotonic Alignment Search) ──
    def mas(value: np.ndarray) -> np.ndarray:
        """단조 정렬: 프레임마다 토큰 하나를 고르되, 앞 토큰으로 돌아가지도 건너뛰지도 않고(0칸 또는 1칸 전진),
        첫 프레임은 첫 토큰, 마지막 프레임은 마지막 토큰. 점수 합이 가장 큰 길을 0/1 표로 돌려준다."""
        T, N = value.shape
        Q = np.full((T, N), -1e9)
        Q[0, 0] = value[0, 0]
        for t in range(1, T):
            for j in range(min(t + 1, N)):
                Q[t, j] = max(Q[t - 1, j], Q[t - 1, j - 1] if j > 0 else -1e9) + value[t, j]
        path, j = np.zeros((T, N), int), N - 1
        for t in range(T - 1, -1, -1):
            path[t, j] = 1
            if t > 0 and j > 0 and Q[t - 1, j - 1] > Q[t - 1, j]:
                j -= 1                                                 # 이 프레임에서 토큰이 바뀌었다
        return path


    def token_seconds(path: np.ndarray, hop: int = 256, sr: int = 16000) -> np.ndarray:
        """정렬의 길에서 토큰마다의 길이(초) = 프레임 수 x hop / sr."""
        return path.sum(0) * hop / sr


    check(np.allclose(token_seconds(np.array([[1, 0], [1, 0], [0, 1]])), [0.032, 0.016]), "토큰의 길이(초) = 프레임 수 x hop / sr")
    rng = np.random.default_rng(1)
    true_d = rng.integers(3, 9, 8)                                       # 토큰 8개의 실제 길이(프레임)
    who = np.repeat(np.arange(8), true_d)
    value = rng.normal(0, 0.5, (len(who), 8))
    value[np.arange(len(who)), who] += 2.0                               # [대체] 텍스트 인코더 · 음향 모델 대신: 실제 토큰에 점수가 높은 합성 표
    path = mas(value)
    got = path.sum(0)
    print("실제 길이:", true_d.tolist(), "\n찾은 길이:", got.tolist(), f"· 프레임 {len(who)}개 · 길의 점수 {float((path * value).sum()):.1f}")
    tok_of_frame = path.argmax(1)
    check(got.sum() == len(who) and got.min() >= 1 and (path.sum(1) == 1).all() and set(np.diff(tok_of_frame)) <= {0, 1}
          and tok_of_frame[0] == 0 and tok_of_frame[-1] == 7 and np.abs(got - true_d).max() <= 1,
          "모든 프레임이 토큰 하나에 속하고, 토큰은 0 → 7 순서로 한 칸씩만 전진하고, 실제 길이와 1프레임 안에서 맞아야 해요.")


def _part_loss():
    # ── Part 2-3 · 다섯 손실 ──
    W = dict(mel=35.0, kl=1.5, dur=1.0, gen=1.0, fmaps=1.0)             # 손실의 가중치(판별기 손실은 판별기 걸음에서 따로)


    def mel_loss(pred, target):
        """멜 스펙트로그램 L1: 소리의 모양이 같아지게."""
        return float(np.mean(np.abs(pred - target)))


    def kl_loss(m_q, logs_q, m_p, logs_p):
        """두 정규분포 N(m_q, e^logs_q)와 N(m_p, e^logs_p)의 KL: 글자에서 예측한 분포와 소리에서 구한 분포를 가깝게."""
        return float(np.mean(logs_p - logs_q - 0.5 + 0.5 * (np.exp(2 * logs_q) + (m_q - m_p) ** 2) * np.exp(-2 * logs_p)))


    def dur_loss(log_d_pred, d_true):
        """길이 손실: 로그 길이의 제곱 오차."""
        return float(np.mean((log_d_pred - np.log(d_true)) ** 2))


    def gen_loss(d_fake):
        """생성기(LSGAN): 가짜가 판별기에게 1(진짜)로 보이게."""
        return float(np.mean((1 - d_fake) ** 2))


    def disc_loss(d_real, d_fake):
        """판별기(LSGAN): 진짜는 1, 가짜는 0으로."""
        return float(np.mean((1 - d_real) ** 2) + np.mean(d_fake ** 2))


    def fmap_loss(f_real: list, f_fake: list):
        """특징 일치: 판별기 중간 층의 특징이 진짜와 가짜에서 비슷해지게."""
        return float(sum(np.mean(np.abs(a - b)) for a, b in zip(f_real, f_fake)))


    rng = np.random.default_rng(0)
    target = rng.normal(0, 1, (80, 50))
    pred = target + 0.3 * rng.standard_normal(target.shape)
    L = {"mel": mel_loss(pred, target), "kl": kl_loss(np.full(10, 0.5), np.full(10, 0.1), np.zeros(10), np.zeros(10)),
         "dur": dur_loss(np.log(np.array([4.0, 6.0, 5.0])) + 0.2, np.array([4.0, 6.0, 5.0])), "gen": gen_loss(np.array([0.3, 0.5])),
         "fmaps": fmap_loss([target[:10]], [pred[:10]])}
    total = sum(W[k] * v for k, v in L.items())
    for k, v in L.items():
        print(f"{k:>6}: 손실 {v:.3f} x 가중치 {W[k]:>4} = {W[k] * v:6.3f} ({W[k] * v / total:.0%})")
    print(f"합계 {total:.3f} · 판별기 손실(따로) {disc_loss(np.array([0.9, 0.8]), np.array([0.3, 0.2])):.3f}")
    check(mel_loss(target, target) == 0 and abs(kl_loss(np.array([1.0]), np.array([0.0]), np.array([0.0]), np.array([0.0])) - 0.5) < 1e-12
          and abs(kl_loss(np.array([0.0]), np.array([math.log(2)]), np.array([0.0]), np.array([0.0])) - 0.8069) < 1e-3
          and abs(dur_loss(np.log(np.array([2.0])) + 0.2, np.array([2.0])) - 0.04) < 1e-12 and gen_loss(np.ones(3)) == 0 and abs(disc_loss(np.ones(2), np.zeros(2))) < 1e-12
          and max(L, key=lambda k: W[k] * L[k]) == "mel", "같으면 0, KL(N(1,1)||N(0,1)) = 0.5, 가중합에서는 멜 손실이 가장 커야 해요.")


def _part_steps():
    # ── Part 3 · 걸음 수와 과적합: 체크포인트 고르기 ──
    # [대체] VITS 대신 장난감 '화자 파라미터' 학습. 파라미터 20개가 각자 다른 속도(lam)로 학습되고, 학습 데이터에 잡음이 섞여 있어
    # 정답(모두 1) 대신 '잡음이 섞인 해'(target)를 향해 간다. 느리게 배우는 파라미터일수록 잡음 때문에 많이 틀려서 오래 학습하면 평가 오차가 다시 올라간다.
    F, C = 20, 0.2
    lam = 10 ** (-3 * np.arange(F) / (F - 1))                              # 배우는 속도: 1 ~ 0.001
    target = 1 + C / np.sqrt(lam) * np.where(np.arange(F) % 2 == 0, 1.0, -1.0)   # 적은 데이터가 만든 잡음 섞인 해
    w_star = np.ones(F)                                                    # 목표 화자의 진짜 파라미터
    base_err = float(np.sum(lam * w_star ** 2))                            # 걸음 0의 평가 오차
    rows = []
    for step in range(0, 6001, 300):
        w = target * (1 - (1 - 0.5 * lam) ** step)                         # 경사하강법(학습률 0.5)을 step번 한 결과
        rows.append({"step": step, "train": float(np.sum(lam * (w - target) ** 2)), "cer": min(1.0, float(np.sum(lam * (w - w_star) ** 2)) / base_err),
                     "sim": float(w @ w_star / (np.linalg.norm(w) * np.linalg.norm(w_star) + 1e-12))})


    def pick_best(rows: list, max_cer: float):
        """발음 오류(cer)가 한도 이하인 체크포인트 가운데 화자 유사도가 가장 높은 걸음. 없으면 None."""
        ok = [r for r in rows if r["cer"] <= max_cer]
        return max(ok, key=lambda r: r["sim"])["step"] if ok else None


    for r in rows[::2]:
        print(f"걸음 {r['step']:>5}: 학습 손실 {r['train']:.3f} · 발음 오류(대용) {r['cer']:.3f} · 화자 유사도 {r['sim']:.3f}")
    MAX_CER = 1.1 * min(r["cer"] for r in rows)
    best = pick_best(rows, MAX_CER)
    print(f"발음 한도 {MAX_CER:.3f} → 고른 걸음 {best} (마지막 {rows[-1]['step']})")
    check(all(a["train"] >= b["train"] - 1e-9 for a, b in zip(rows, rows[1:])) and min(rows, key=lambda r: r["cer"])["step"] not in (0, rows[-1]["step"])
          and rows[-1]["cer"] > MAX_CER and best is not None and 0 < best < rows[-1]["step"]
          and pick_best([{"step": 1, "cer": 0.2, "sim": 0.9}, {"step": 2, "cer": 0.05, "sim": 0.7}], 0.1) == 2 and pick_best([{"step": 1, "cer": 0.5, "sim": 0.9}], 0.1) is None,
          "학습 손실은 계속 내려가지만 평가 오차는 중간에서 가장 낮고 다시 올라가요. 발음 한도 안에서 가장 닮은 걸음을 골라야 해요.")


def _part_evalm():
    # ── Part 4 · 세 가지 평가: 발음 · 화자 유사도 · 자연스러움 ──
    def f0_and_r(y: np.ndarray) -> tuple:
        """큰 조각들의 높낮이(Hz, 자기상관)와 주기성 r(0~1, 자기상관 봉우리 / 0칸 값): 맑을수록 r이 크다."""
        db = frame_db(y)
        fs, rs = [], []
        for i in np.where(db > db.max() - 6)[0][::4]:
            x = y[i * HOP:i * HOP + 640] - y[i * HOP:i * HOP + 640].mean()
            ac = np.array([np.dot(x[:-lag], x[lag:]) for lag in range(40, 229)])
            k = int(np.argmax(ac))
            fs.append(SR / (40 + k))
            rs.append(ac[k] / np.dot(x, x))
        return float(np.median(fs)), float(np.clip(np.mean(rs), 0, 1))


    TARGET_F0 = 200.0
    rng = np.random.default_rng(2)
    systems = {"파인튜닝 전": burst(12, 120, 0.3, 0.005, seed=1),                               # 다른 사람 목소리지만 깨끗함
               "파인튜닝 후": burst(12, 205, 0.3, 0.03, seed=2),                                # 목표 화자에 가깝지만 조금 떨리고 잡음
               "진짜 녹음": burst(12, 200, 0.3, 0.01, seed=3)}
    systems["파인튜닝 후"] = systems["파인튜닝 후"] + (10 ** (-32 / 20) * rng.standard_normal(len(systems["파인튜닝 후"]))).astype(np.float32)
    REPORT = {}
    for name, y in systems.items():
        f0, r = f0_and_r(y)
        sim = max(0.0, 1 - abs(12 * math.log2(f0 / TARGET_F0)) / 12)         # 화자 유사도(대용): 목표 높낮이와의 반음 차이가 작을수록 1
        cer = min(0.5, (1 - r) * 0.5)                                       # 발음 오류(대용): [대체] 받아쓰기 대신 주기성이 낮을수록 더 틀린다고 가정
        REPORT[name] = {"sim": sim, "mos": 1 + 4 * r, "cer": cer}
    print(f"{'':<12}{'화자 유사도':>10}{'자연스러움(1~5)':>16}{'발음 오류율':>12}")
    for name, m in REPORT.items():
        print(f"{name:<12}{m['sim']:>10.2f}{m['mos']:>16.2f}{m['cer']:>12.1%}")
    b, a, real = REPORT["파인튜닝 전"], REPORT["파인튜닝 후"], REPORT["진짜 녹음"]
    check(a["sim"] - b["sim"] > 0.5 and a["sim"] > 0.9 and real["mos"] >= a["mos"] and b["mos"] > 3 and all(0 <= m["cer"] <= 0.5 for m in REPORT.values()),
          "파인튜닝 후에는 화자 유사도가 크게 올라가고, 자연스러움은 진짜 녹음이 가장 높아야 해요. 한 가지 자만 보면 안 돼요.")


def _part_wm():
    # ── Part 4-2 · 워터마크: 합성음임을 표시하기 ──
    def key_seq(key: int, n: int) -> np.ndarray:
        """열쇠(key)로 만든 +1 / -1 수열: 열쇠를 아는 사람만 같은 수열을 만들 수 있다."""
        return np.random.default_rng(key).choice([-1.0, 1.0], n)


    def wm_score(y: np.ndarray, key: int) -> float:
        """열쇠 수열과의 상관을 표준화한 z 점수: 표시가 없으면 평균 0, 표준편차 1 근처."""
        return float(np.dot(y, key_seq(key, len(y))) / (np.std(y) * math.sqrt(len(y))))


    def add_watermark(y: np.ndarray, key: int, db: float = -26.0) -> np.ndarray:
        """말 크기(RMS)보다 db만큼 작은 열쇠 수열을 더한다."""
        return (y + 10 ** (db / 20) * np.sqrt(np.mean(y ** 2)) * key_seq(key, len(y))).astype(np.float32)


    def detect(y: np.ndarray, key: int, th: float = 4.0) -> tuple:
        z = wm_score(y, key)
        return z, z > th


    KEY = 1234
    rng = np.random.default_rng(0)
    clean = burst(25, 140, 0.3, 0.01, seed=1) + (0.001 * rng.standard_normal(25 * int(0.18 * SR))).astype(np.float32)
    marked = add_watermark(clean, KEY)
    tests = {"표시 없음": detect(clean, KEY), "표시 있음": detect(marked, KEY), "다른 열쇠로 검사": detect(marked, KEY + 1),
             "잡음 20 dB 추가": detect(marked + (10 ** (-20 / 20) * np.sqrt(np.mean(marked ** 2)) * rng.standard_normal(len(marked))).astype(np.float32), KEY),
             "저역 통과(2개 평균)": detect(np.r_[marked[0], (marked[1:] + marked[:-1]) / 2].astype(np.float32), KEY),
             "속도 1.1배": detect(np.interp(np.arange(0, len(marked) - 1, 1.1), np.arange(len(marked)), marked).astype(np.float32), KEY)}
    for name, (z, hit) in tests.items():
        print(f"{name:<16} z = {z:6.1f} → {'표시 검출' if hit else '검출 안 됨'}")
    snr_wm = 10 * math.log10(np.mean(clean ** 2) / np.mean((marked - clean) ** 2))
    print(f"더한 표시의 크기: 말 대비 {snr_wm:.0f} dB")
    check(not tests["표시 없음"][1] and tests["표시 있음"][1] and not tests["다른 열쇠로 검사"][1] and tests["잡음 20 dB 추가"][1] and tests["저역 통과(2개 평균)"][1]
          and not tests["속도 1.1배"][1] and abs(snr_wm - 26) < 1,
          "열쇠가 맞고 표시가 있을 때만 검출돼요. 잡음 · 저역 통과는 견디지만 속도를 바꾸면 못 찾는다는 한계도 기억하세요.")


_part_dataq()
_part_text()
_part_mas()
_part_loss()
_part_steps()
_part_evalm()
_part_wm()

flow.typescript:
// D40 · Part 0~4 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d40_flow.ts   (소리·데이터는 코드 안에서 합성해요)
//   목소리 데이터 거르기 → 글자 정규화와 토큰 → 단조 정렬 → 다섯 손실 → 걸음 수와 과적합 → 평가 → 워터마크를 장난감 모델로 한 번에


const SR = 16000; // 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}


function burst(nSyl: number, f0: number, amp: number = 0.3, jitter: number = 0, seed: number = 0): Float32Array {
  // [대체] TTS 대신 합성 목소리: 음절 nSyl개(0.18초, 앞 85%가 소리). jitter는 높낮이가 떨리는 정도, 음절마다 배음 2개
  const rnd = mulberry32(seed);
  const L = Math.floor(0.18 * SR);
  const m = Math.floor(L * 0.85);
  const y = new Float32Array(nSyl * L);
  for (let i = 0; i < nSyl; i++) {
    const f = f0 * (1 + jitter * gauss(rnd));
    for (let j = 0; j < m; j++) {
      const s = Math.sin((2 * Math.PI * f * j) / SR) + 0.4 * Math.sin((2 * Math.PI * 2 * f * j) / SR);
      y[i * L + j] = ((amp * s) / 1.4) * (0.5 - 0.5 * Math.cos((2 * Math.PI * j) / (m - 1)));
    }
  }
  return y;
}


// ── Part 1 · 목소리 데이터 준비: TTS 데이터의 기준 ──
{
  const TARGET_DB = -23.0; // 학습용 음량(RMS, dBFS)

  function quality(y: Float32Array): [number, number] {
    // [SNR dB, 깨진 표본의 비율]: 큰 조각의 전력과 가장 조용한 10% 조각의 전력을 비교
    const db = frameDb(y);
    const p = db.map((d) => 10 ** (d / 10));
    const med = percentile(db, 50);
    const loud = p.filter((_, i) => db[i] > med);
    const quiet = [...p].sort((a, b) => a - b).slice(0, Math.max(1, Math.floor(p.length / 10)));
    const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
    return [10 * Math.log10(mean(loud) / mean(quiet)), y.filter((v) => Math.abs(v) >= 0.999).length / y.length];
  }

  function prepWav(y: Float32Array, topDb: number = 35.0, pad: number = 0.1): Float32Array {
    // 앞뒤 침묵(가장 큰 곳보다 topDb 넘게 작은 곳)을 pad만 남기고 자르고, RMS를 TARGET_DB로 맞춘다
    const db = frameDb(y);
    const mx = Math.max(...db);
    const idx = db.map((d, i) => (d > mx - topDb ? i : -1)).filter((i) => i >= 0);
    const a = Math.max(0, idx[0] * HOP - Math.floor(pad * SR));
    const b = Math.min(y.length, idx[idx.length - 1] * HOP + 640 + Math.floor(pad * SR));
    const cut = y.slice(a, b);
    const g = 10 ** (TARGET_DB / 20) / Math.sqrt(power(cut));
    return cut.map((v) => Math.max(-1, Math.min(1, v * g)));
  }

  function makeUtt(kind: string, seed: number): Float32Array {
    const rnd = mulberry32(seed);
    const quiet = (s: number): Float32Array => Float32Array.from({ length: Math.floor(s * SR) }, () => 10 ** (-60 / 20) * gauss(rnd)); // 조용한 방 잡음 -60 dB
    let y: Float32Array;
    if (kind === "clipped") y = burst(12, 150, 3.0, 0, seed).map((v) => Math.max(-1, Math.min(1, v))); // 입력이 너무 커서 깨짐
    else if (kind === "short") y = burst(2, 150, 0.3, 0, seed); // 0.36초: 너무 짧음
    else if (kind === "longlead") {
      const b = burst(12, 150, 0.3, 0, seed);
      y = new Float32Array(Math.floor(2.5 * SR) + b.length); // 앞에 2.5초 침묵
      y.set(b, Math.floor(2.5 * SR));
    } else y = burst(12, 150, 0.3, 0, seed);
    const parts = [quiet(0.4), y, quiet(0.4)];
    const out = new Float32Array(parts.reduce((s, p) => s + p.length, 0));
    let off = 0;
    for (const p of parts) {
      out.set(p, off);
      off += p.length;
    }
    if (kind === "noisy") for (let i = 0; i < out.length; i++) out[i] += 10 ** (-22 / 20) * gauss(rnd);
    return out;
  }

  const KINDS = [...Array(7).fill("good"), "clipped", "noisy", "short", "longlead"] as string[];
  interface Row {
    kind: string;
    ok: boolean;
    rms: number;
    lead: number;
  }
  const rows: Row[] = [];
  KINDS.forEach((kind, i) => {
    const raw = makeUtt(kind, i);
    const [snr, clip] = quality(raw);
    const y = prepWav(raw);
    const sec = y.length / SR;
    const ok = clip < 0.001 && snr >= 25 && sec >= 1.0 && sec <= 12;
    rows.push({ kind, ok, rms: 20 * Math.log10(Math.sqrt(power(y))), lead: y.findIndex((v) => Math.abs(v) > 0.01) / SR });
    console.log(`${kind}: SNR ${snr.toFixed(1)} dB · 깨진 표본 ${(clip * 100).toFixed(2)}% · 길이 ${sec.toFixed(1)}초 → ${ok ? "사용" : "버림"}`);
  });
  const kept = rows.filter((r) => r.ok).map((r) => r.kind);
  check(
    kept.filter((k) => k === "good").length === 7 &&
      kept.includes("longlead") &&
      !["clipped", "noisy", "short"].some((k) => kept.includes(k)) &&
      rows.filter((r) => r.kind !== "clipped").every((r) => Math.abs(r.rms - TARGET_DB) < 0.1) &&
      rows.filter((r) => r.ok).every((r) => r.lead < 0.3),
    "깨진 소리 · 잡음 · 너무 짧은 녹음은 버리고, 앞 침묵은 잘라내며 음량은 -23 dB로 맞춰져야 해요.",
  );
}


// ── Part 1-3 · 글자를 소리 나는 대로: 정규화 → 토큰 ──
{
  const SINO = "영일이삼사오육칠팔구";
  const NATIVE: Record<number, string> = { 1: "한", 2: "두", 3: "세", 4: "네", 5: "다섯", 6: "여섯", 7: "일곱", 8: "여덟", 9: "아홉" };
  const TENS: Record<number, string> = { 1: "열", 2: "스물", 3: "서른", 4: "마흔", 5: "쉰", 6: "예순", 7: "일흔", 8: "여든", 9: "아흔" };
  const NATIVE_UNITS = "시|개|명|살|잔|달|번"; // 고유어(하나 둘 셋)로 읽는 단위

  function readNumber(n: number): string {
    // 0 ~ 9999를 한자어로: 천 · 백 · 십 앞의 1은 읽지 않는다(123 → 백이십삼)
    if (n === 0) return "영";
    let out = "";
    let rest = n;
    for (const [div, unit] of [[1000, "천"], [100, "백"], [10, "십"]] as Array<[number, string]>) {
      const d = Math.floor(rest / div);
      rest %= div;
      if (d) out += (d === 1 ? "" : SINO[d]) + unit;
    }
    return out + (rest ? SINO[rest] : "");
  }

  function readBig(n: number): string {
    // 만 단위 이상: 네 자리씩 끊어 읽는다(15000 → 만 오천)
    const q = Math.floor(n / 10000);
    const r = n % 10000;
    if (q === 0) return readNumber(r);
    return (q === 1 ? "만" : `${readNumber(q)}만`) + (r ? ` ${readNumber(r)}` : "");
  }

  function readNative(n: number): string {
    // 1 ~ 99를 고유어로(세 · 두 · 열두 · 스무)
    if (n === 20) return "스무";
    const t = Math.floor(n / 10);
    const u = n % 10;
    return (t ? TENS[t] : "") + (u ? NATIVE[u] : "");
  }

  function normalizeText(text: string): string {
    const a = text.replace(new RegExp(`(\\d+)(${NATIVE_UNITS})`, "g"), (_, n: string, unit: string) => `${Number(n) > 0 && Number(n) < 100 ? readNative(Number(n)) : readBig(Number(n))} ${unit}`);
    return a.replace(/(\d+)([가-힣]?)/g, (_, n: string, unit: string) => readBig(Number(n)) + (unit ? ` ${unit}` : ""));
  }

  function toIds(text: string): number[] {
    // 한글 → 초성(0~18) · 중성(19~39) · 종성(40~66) 토큰, 공백은 99. 유니코드 계산만으로 쪼갠다
    const out: number[] = [];
    for (const c of text) {
      if (c >= "가" && c <= "힣") {
        const code = (c.codePointAt(0) as number) - 0xac00;
        out.push(Math.floor(code / 588), 19 + Math.floor((code % 588) / 28));
        if (code % 28) out.push(40 + (code % 28) - 1);
      } else out.push(99);
    }
    return out;
  }

  function fromIds(ids: number[]): string {
    let out = "";
    let i = 0;
    while (i < ids.length) {
      if (ids[i] === 99) {
        out += " ";
        i++;
        continue;
      }
      let code = ids[i] * 588 + (ids[i + 1] - 19) * 28;
      i += 2;
      if (i < ids.length && ids[i] >= 40 && ids[i] <= 66) {
        code += ids[i] - 40 + 1;
        i++;
      }
      out += String.fromCodePoint(0xac00 + code);
    }
    return out;
  }

  const raw = "오후 3시 30분에 2명 예약, 비용 15000원";
  const norm = normalizeText(raw);
  console.log(raw, "→", norm);
  const ids = toIds("한글 말해요");
  console.log("토큰:", ids.join(", "), "→ 되돌리기:", fromIds(ids));
  check(
    [0, 10, 11, 123, 1000, 2024, 9999].map(readNumber).join() === ["영", "십", "십일", "백이십삼", "천", "이천이십사", "구천구백구십구"].join() &&
      [3, 12, 20, 21].map(readNative).join() === ["세", "열두", "스무", "스물한"].join() &&
      norm === "오후 세 시 삼십 분에 두 명 예약, 비용 만 오천 원" &&
      toIds("한글").join() === [18, 19, 43, 0, 37, 47].join() &&
      fromIds(ids) === "한글 말해요",
    "123 → 백이십삼, 3시 → 세 시, 15000 → 만 오천, 한 → [18, 19, 43]이어야 해요.",
  );
}


// ── Part 2 · 단조 정렬(Monotonic Alignment Search) ──
{
  function mas(value: number[][]): number[][] {
    // 단조 정렬: 프레임마다 토큰 하나를 고르되, 앞 토큰으로 돌아가지도 건너뛰지도 않고(0칸 또는 1칸 전진),
    // 첫 프레임은 첫 토큰, 마지막 프레임은 마지막 토큰. 점수 합이 가장 큰 길을 0/1 표로 돌려준다
    const T = value.length;
    const N = value[0].length;
    const Q = Array.from({ length: T }, () => new Array<number>(N).fill(-1e9));
    Q[0][0] = value[0][0];
    for (let t = 1; t < T; t++) for (let j = 0; j < Math.min(t + 1, N); j++) Q[t][j] = Math.max(Q[t - 1][j], j > 0 ? Q[t - 1][j - 1] : -1e9) + value[t][j];
    const path = Array.from({ length: T }, () => new Array<number>(N).fill(0));
    let j = N - 1;
    for (let t = T - 1; t >= 0; t--) {
      path[t][j] = 1;
      if (t > 0 && j > 0 && Q[t - 1][j - 1] > Q[t - 1][j]) j--; // 이 프레임에서 토큰이 바뀌었다
    }
    return path;
  }

  function tokenSeconds(path: number[][], hop: number = 256, sr: number = 16000): number[] {
    // 정렬의 길에서 토큰마다의 길이(초) = 프레임 수 x hop / sr
    return path[0].map((_, j) => (path.reduce((s, row) => s + row[j], 0) * hop) / sr);
  }

  const ts0 = tokenSeconds([[1, 0], [1, 0], [0, 1]]);
  check(Math.abs(ts0[0] - 0.032) < 1e-12 && Math.abs(ts0[1] - 0.016) < 1e-12, "토큰의 길이(초) = 프레임 수 x hop / sr");
  const rnd = mulberry32(1);
  const trueD = Array.from({ length: 8 }, () => 3 + Math.floor(rnd() * 6)); // 토큰 8개의 실제 길이(프레임)
  const who = trueD.flatMap((d, k) => new Array<number>(d).fill(k));
  const value = who.map((k) => Array.from({ length: 8 }, (_, j) => 0.5 * gauss(rnd) + (j === k ? 2 : 0))); // [대체] 텍스트 인코더 · 음향 모델 대신: 실제 토큰에 점수가 높은 합성 표
  const path = mas(value);
  const got = path[0].map((_, j) => path.reduce((s, row) => s + row[j], 0));
  const score = path.reduce((s, row, t) => s + row.reduce((a, v, j) => a + v * value[t][j], 0), 0);
  console.log(`실제 길이: [${trueD}]\n찾은 길이: [${got}] · 프레임 ${who.length}개 · 길의 점수 ${score.toFixed(1)}`);
  const tokOf = path.map((row) => row.indexOf(1));
  check(
    got.reduce((a, b) => a + b, 0) === who.length &&
      Math.min(...got) >= 1 &&
      path.every((row) => row.reduce((a, b) => a + b, 0) === 1) &&
      tokOf.every((k, t) => t === 0 || k - tokOf[t - 1] === 0 || k - tokOf[t - 1] === 1) &&
      tokOf[0] === 0 &&
      tokOf[tokOf.length - 1] === 7 &&
      Math.max(...got.map((g, k) => Math.abs(g - trueD[k]))) <= 1,
    "모든 프레임이 토큰 하나에 속하고, 토큰은 0 → 7 순서로 한 칸씩만 전진하고, 실제 길이와 1프레임 안에서 맞아야 해요.",
  );
}


// ── Part 2-3 · 다섯 손실 ──
{
  const W: Record<string, number> = { mel: 35.0, kl: 1.5, dur: 1.0, gen: 1.0, fmaps: 1.0 }; // 손실의 가중치(판별기 손실은 판별기 걸음에서 따로)
  const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;

  function melLoss(pred: number[], target: number[]): number {
    // 멜 스펙트로그램 L1: 소리의 모양이 같아지게
    return mean(pred.map((p, i) => Math.abs(p - target[i])));
  }

  function klLoss(mq: number[], logsQ: number[], mp: number[], logsP: number[]): number {
    // 두 정규분포 N(m_q, e^logs_q)와 N(m_p, e^logs_p)의 KL: 글자에서 예측한 분포와 소리에서 구한 분포를 가깝게
    return mean(mq.map((_, i) => logsP[i] - logsQ[i] - 0.5 + 0.5 * (Math.exp(2 * logsQ[i]) + (mq[i] - mp[i]) ** 2) * Math.exp(-2 * logsP[i])));
  }

  function durLoss(logDPred: number[], dTrue: number[]): number {
    // 길이 손실: 로그 길이의 제곱 오차
    return mean(logDPred.map((p, i) => (p - Math.log(dTrue[i])) ** 2));
  }

  function genLoss(dFake: number[]): number {
    // 생성기(LSGAN): 가짜가 판별기에게 1(진짜)로 보이게
    return mean(dFake.map((v) => (1 - v) ** 2));
  }

  function discLoss(dReal: number[], dFake: number[]): number {
    // 판별기(LSGAN): 진짜는 1, 가짜는 0으로
    return mean(dReal.map((v) => (1 - v) ** 2)) + mean(dFake.map((v) => v ** 2));
  }

  function fmapLoss(fReal: number[][], fFake: number[][]): number {
    // 특징 일치: 판별기 중간 층의 특징이 진짜와 가짜에서 비슷해지게
    return fReal.reduce((s, a, k) => s + mean(a.map((v, i) => Math.abs(v - fFake[k][i]))), 0);
  }

  const rnd = mulberry32(0);
  const target = Array.from({ length: 80 * 50 }, () => gauss(rnd));
  const pred = target.map((v) => v + 0.3 * gauss(rnd));
  const dTrue = [4, 6, 5];
  const L: Record<string, number> = {
    mel: melLoss(pred, target),
    kl: klLoss(new Array(10).fill(0.5), new Array(10).fill(0.1), new Array(10).fill(0), new Array(10).fill(0)),
    dur: durLoss(dTrue.map((d) => Math.log(d) + 0.2), dTrue),
    gen: genLoss([0.3, 0.5]),
    fmaps: fmapLoss([target.slice(0, 500)], [pred.slice(0, 500)]),
  };
  const total = Object.entries(L).reduce((s, [k, v]) => s + W[k] * v, 0);
  for (const [k, v] of Object.entries(L)) console.log(`${k}: 손실 ${v.toFixed(3)} x 가중치 ${W[k]} = ${(W[k] * v).toFixed(3)} (${((W[k] * v / total) * 100).toFixed(0)}%)`);
  console.log(`합계 ${total.toFixed(3)} · 판별기 손실(따로) ${discLoss([0.9, 0.8], [0.3, 0.2]).toFixed(3)}`);
  check(
    melLoss(target, target) === 0 &&
      Math.abs(klLoss([1], [0], [0], [0]) - 0.5) < 1e-12 &&
      Math.abs(klLoss([0], [Math.log(2)], [0], [0]) - 0.8069) < 1e-3 &&
      Math.abs(durLoss([Math.log(2) + 0.2], [2]) - 0.04) < 1e-12 &&
      genLoss([1, 1, 1]) === 0 &&
      Math.abs(discLoss([1, 1], [0, 0])) < 1e-12 &&
      Object.keys(L).reduce((p, q) => (W[q] * L[q] > W[p] * L[p] ? q : p)) === "mel",
    "같으면 0, KL(N(1,1)||N(0,1)) = 0.5, 가중합에서는 멜 손실이 가장 커야 해요.",
  );
}


// ── Part 3 · 걸음 수와 과적합: 체크포인트 고르기 ──
{
  // [대체] VITS 대신 장난감 '화자 파라미터' 학습. 파라미터 20개가 각자 다른 속도(lam)로 학습되고, 학습 데이터에 잡음이 섞여 있어
  // 정답(모두 1) 대신 '잡음이 섞인 해'(target)를 향해 간다. 느리게 배우는 파라미터일수록 잡음 때문에 많이 틀려서 오래 학습하면 평가 오차가 다시 올라간다.
  const F = 20;
  const C = 0.2;
  const lam = Array.from({ length: F }, (_, i) => 10 ** ((-3 * i) / (F - 1))); // 배우는 속도: 1 ~ 0.001
  const target = lam.map((l, i) => 1 + (C / Math.sqrt(l)) * (i % 2 === 0 ? 1 : -1)); // 적은 데이터가 만든 잡음 섞인 해
  const baseErr = lam.reduce((s, l) => s + l, 0); // 걸음 0의 평가 오차(진짜 파라미터는 모두 1)

  interface Ckpt {
    step: number;
    train: number;
    cer: number;
    sim: number;
  }

  const rows: Ckpt[] = [];
  for (let step = 0; step <= 6000; step += 300) {
    const w = target.map((t, i) => t * (1 - (1 - 0.5 * lam[i]) ** step)); // 경사하강법(학습률 0.5)을 step번 한 결과
    const dot = w.reduce((s, v) => s + v, 0);
    rows.push({
      step,
      train: w.reduce((s, v, i) => s + lam[i] * (v - target[i]) ** 2, 0),
      cer: Math.min(1, w.reduce((s, v, i) => s + lam[i] * (v - 1) ** 2, 0) / baseErr),
      sim: dot / (Math.sqrt(w.reduce((s, v) => s + v * v, 0)) * Math.sqrt(F) + 1e-12),
    });
  }

  function pickBest(rs: Ckpt[], maxCer: number): number | null {
    // 발음 오류(cer)가 한도 이하인 체크포인트 가운데 화자 유사도가 가장 높은 걸음. 없으면 null
    const ok = rs.filter((r) => r.cer <= maxCer);
    return ok.length ? ok.reduce((p, q) => (q.sim > p.sim ? q : p)).step : null;
  }

  rows.forEach((r, i) => {
    if (i % 2 === 0) console.log(`걸음 ${r.step}: 학습 손실 ${r.train.toFixed(3)} · 발음 오류(대용) ${r.cer.toFixed(3)} · 화자 유사도 ${r.sim.toFixed(3)}`);
  });
  const MAX_CER = 1.1 * Math.min(...rows.map((r) => r.cer));
  const best = pickBest(rows, MAX_CER);
  const last = rows[rows.length - 1];
  const minRow = rows.reduce((p, q) => (q.cer < p.cer ? q : p));
  console.log(`발음 한도 ${MAX_CER.toFixed(3)} → 고른 걸음 ${best} (마지막 ${last.step})`);
  check(
    rows.every((a, i) => i === 0 || rows[i - 1].train >= a.train - 1e-9) &&
      minRow.step !== 0 &&
      minRow.step !== last.step &&
      last.cer > MAX_CER &&
      best !== null &&
      best > 0 &&
      best < last.step &&
      pickBest([{ step: 1, train: 0, cer: 0.2, sim: 0.9 }, { step: 2, train: 0, cer: 0.05, sim: 0.7 }], 0.1) === 2 &&
      pickBest([{ step: 1, train: 0, cer: 0.5, sim: 0.9 }], 0.1) === null,
    "학습 손실은 계속 내려가지만 평가 오차는 중간에서 가장 낮고 다시 올라가요. 발음 한도 안에서 가장 닮은 걸음을 골라야 해요.",
  );
}


// ── Part 4 · 세 가지 평가: 발음 · 화자 유사도 · 자연스러움 ──
{
  function f0AndR(y: Float32Array): [number, number] {
    // 큰 조각들의 높낮이(Hz, 자기상관)와 주기성 r(0~1, 자기상관 봉우리 / 0칸 값): 맑을수록 r이 크다
    const db = frameDb(y);
    const mx = Math.max(...db);
    const loud = db.map((d, i) => (d > mx - 6 ? i : -1)).filter((i) => i >= 0).filter((_, k) => k % 4 === 0);
    const fs: number[] = [];
    const rs: number[] = [];
    for (const i of loud) {
      const x = y.slice(i * HOP, i * HOP + 640);
      const m = x.reduce((s, v) => s + v, 0) / 640;
      const xc = x.map((v) => v - m);
      let best = -Infinity;
      let bk = 0;
      for (let lag = 40; lag < 229; lag++) {
        let s = 0;
        for (let t = 0; t < 640 - lag; t++) s += xc[t] * xc[t + lag];
        if (s > best) {
          best = s;
          bk = lag;
        }
      }
      fs.push(SR / bk);
      rs.push(best / xc.reduce((s, v) => s + v * v, 0));
    }
    const s = [...fs].sort((a, b) => a - b);
    const r = rs.reduce((a, b) => a + b, 0) / rs.length;
    return [s.length % 2 ? s[s.length >> 1] : (s[s.length / 2 - 1] + s[s.length / 2]) / 2, Math.max(0, Math.min(1, r))];
  }

  const TARGET_F0 = 200.0;
  const rnd = mulberry32(2);
  const after = burst(12, 205, 0.3, 0.03, 2); // 목표 화자에 가깝지만 조금 떨리고 잡음
  const afterNoisy = after.map((v) => v + 10 ** (-32 / 20) * gauss(rnd));
  const systems: Record<string, Float32Array> = {
    "파인튜닝 전": burst(12, 120, 0.3, 0.005, 1), // 다른 사람 목소리지만 깨끗함
    "파인튜닝 후": afterNoisy,
    "진짜 녹음": burst(12, 200, 0.3, 0.01, 3),
  };
  const REPORT: Record<string, { sim: number; mos: number; cer: number }> = {};
  console.log("      | 화자 유사도 | 자연스러움(1~5) | 발음 오류율");
  for (const [name, y] of Object.entries(systems)) {
    const [f0, r] = f0AndR(y);
    const sim = Math.max(0, 1 - Math.abs(12 * Math.log2(f0 / TARGET_F0)) / 12); // 화자 유사도(대용): 목표 높낮이와의 반음 차이가 작을수록 1
    const cer = Math.min(0.5, (1 - r) * 0.5); // 발음 오류(대용): [대체] 받아쓰기 대신 주기성이 낮을수록 더 틀린다고 가정
    REPORT[name] = { sim, mos: 1 + 4 * r, cer };
    console.log(`${name} | ${sim.toFixed(2)} | ${(1 + 4 * r).toFixed(2)} | ${(cer * 100).toFixed(1)}%`);
  }
  const b = REPORT["파인튜닝 전"];
  const a = REPORT["파인튜닝 후"];
  const real = REPORT["진짜 녹음"];
  check(
    a.sim - b.sim > 0.5 && a.sim > 0.9 && real.mos >= a.mos && b.mos > 3 && Object.values(REPORT).every((m) => m.cer >= 0 && m.cer <= 0.5),
    "파인튜닝 후에는 화자 유사도가 크게 올라가고, 자연스러움은 진짜 녹음이 가장 높아야 해요. 한 가지 자만 보면 안 돼요.",
  );
}


// ── Part 4-2 · 워터마크: 합성음임을 표시하기 ──
{
  function keySeq(key: number, n: number): Float32Array {
    // 열쇠(key)로 만든 +1 / -1 수열: 열쇠를 아는 사람만 같은 수열을 만들 수 있다
    const r = mulberry32(key);
    return Float32Array.from({ length: n }, () => (r() < 0.5 ? -1 : 1));
  }

  function wmScore(y: Float32Array, key: number): number {
    // 열쇠 수열과의 상관을 표준화한 z 점수: 표시가 없으면 평균 0, 표준편차 1 근처
    const w = keySeq(key, y.length);
    let dot = 0;
    let s = 0;
    let s2 = 0;
    for (let i = 0; i < y.length; i++) {
      dot += y[i] * w[i];
      s += y[i];
      s2 += y[i] * y[i];
    }
    const mean = s / y.length;
    return dot / (Math.sqrt(s2 / y.length - mean * mean) * Math.sqrt(y.length));
  }

  function addWatermark(y: Float32Array, key: number, db: number = -26.0): Float32Array {
    // 말 크기(RMS)보다 db만큼 작은 열쇠 수열을 더한다
    const a = 10 ** (db / 20) * Math.sqrt(power(y));
    const w = keySeq(key, y.length);
    return y.map((v, i) => v + a * w[i]);
  }

  function detect(y: Float32Array, key: number, th: number = 4.0): [number, boolean] {
    const z = wmScore(y, key);
    return [z, z > th];
  }

  const KEY = 1234;
  const rnd = mulberry32(0);
  const speech = burst(25, 140, 0.3, 0.01, 1);
  const clean = speech.map((v) => v + 0.001 * gauss(rnd));
  const marked = addWatermark(clean, KEY);
  const noiseGain = 10 ** (-20 / 20) * Math.sqrt(power(marked));
  const lowpass = marked.map((v, i) => (i === 0 ? v : (v + marked[i - 1]) / 2));
  const n2 = Math.ceil((marked.length - 1) / 1.1);
  const sped = Float32Array.from({ length: n2 }, (_, i) => {
    const x = i * 1.1;
    const k = Math.floor(x);
    return marked[k] + (marked[Math.min(k + 1, marked.length - 1)] - marked[k]) * (x - k);
  });
  const tests: Record<string, [number, boolean]> = {
    "표시 없음": detect(clean, KEY),
    "표시 있음": detect(marked, KEY),
    "다른 열쇠로 검사": detect(marked, KEY + 1),
    "잡음 20 dB 추가": detect(marked.map((v) => v + noiseGain * gauss(rnd)), KEY),
    "저역 통과(2개 평균)": detect(lowpass, KEY),
    "속도 1.1배": detect(sped, KEY),
  };
  for (const [name, [z, hit]] of Object.entries(tests)) console.log(`${name} z = ${z.toFixed(1)} → ${hit ? "표시 검출" : "검출 안 됨"}`);
  const snrWm = 10 * Math.log10(power(clean) / power(marked.map((v, i) => v - clean[i])));
  console.log(`더한 표시의 크기: 말 대비 ${snrWm.toFixed(0)} dB`);
  check(
    !tests["표시 없음"][1] && tests["표시 있음"][1] && !tests["다른 열쇠로 검사"][1] && tests["잡음 20 dB 추가"][1] && tests["저역 통과(2개 평균)"][1] && !tests["속도 1.1배"][1] && Math.abs(snrWm - 26) < 1,
    "열쇠가 맞고 표시가 있을 때만 검출돼요. 잡음 · 저역 통과는 견디지만 속도를 바꾸면 못 찾는다는 한계도 기억하세요.",
  );
}

dataq.typescript:
// D40 · Part 1 · 목소리 데이터 준비: TTS 데이터의 기준 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d40_dataq.ts   (소리·데이터는 코드 안에서 합성해요)
//   앞뒤 침묵 자르기 · 음량 맞추기 · 깨진 소리와 잡음 · 너무 짧은 녹음 거르기


const SR = 16000; // 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}


function burst(nSyl: number, f0: number, amp: number = 0.3, jitter: number = 0, seed: number = 0): Float32Array {
  // [대체] TTS 대신 합성 목소리: 음절 nSyl개(0.18초, 앞 85%가 소리). jitter는 높낮이가 떨리는 정도, 음절마다 배음 2개
  const rnd = mulberry32(seed);
  const L = Math.floor(0.18 * SR);
  const m = Math.floor(L * 0.85);
  const y = new Float32Array(nSyl * L);
  for (let i = 0; i < nSyl; i++) {
    const f = f0 * (1 + jitter * gauss(rnd));
    for (let j = 0; j < m; j++) {
      const s = Math.sin((2 * Math.PI * f * j) / SR) + 0.4 * Math.sin((2 * Math.PI * 2 * f * j) / SR);
      y[i * L + j] = ((amp * s) / 1.4) * (0.5 - 0.5 * Math.cos((2 * Math.PI * j) / (m - 1)));
    }
  }
  return y;
}


const TARGET_DB = -23.0; // 학습용 음량(RMS, dBFS)

function quality(y: Float32Array): [number, number] {
  // [SNR dB, 깨진 표본의 비율]: 큰 조각의 전력과 가장 조용한 10% 조각의 전력을 비교
  const db = frameDb(y);
  const p = db.map((d) => 10 ** (d / 10));
  const med = percentile(db, 50);
  const loud = p.filter((_, i) => db[i] > med);
  const quiet = [...p].sort((a, b) => a - b).slice(0, Math.max(1, Math.floor(p.length / 10)));
  const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
  return [10 * Math.log10(mean(loud) / mean(quiet)), y.filter((v) => Math.abs(v) >= 0.999).length / y.length];
}

function prepWav(y: Float32Array, topDb: number = 35.0, pad: number = 0.1): Float32Array {
  // 앞뒤 침묵(가장 큰 곳보다 topDb 넘게 작은 곳)을 pad만 남기고 자르고, RMS를 TARGET_DB로 맞춘다
  const db = frameDb(y);
  const mx = Math.max(...db);
  const idx = db.map((d, i) => (d > mx - topDb ? i : -1)).filter((i) => i >= 0);
  const a = Math.max(0, idx[0] * HOP - Math.floor(pad * SR));
  const b = Math.min(y.length, idx[idx.length - 1] * HOP + 640 + Math.floor(pad * SR));
  const cut = y.slice(a, b);
  const g = 10 ** (TARGET_DB / 20) / Math.sqrt(power(cut));
  return cut.map((v) => Math.max(-1, Math.min(1, v * g)));
}

function makeUtt(kind: string, seed: number): Float32Array {
  const rnd = mulberry32(seed);
  const quiet = (s: number): Float32Array => Float32Array.from({ length: Math.floor(s * SR) }, () => 10 ** (-60 / 20) * gauss(rnd)); // 조용한 방 잡음 -60 dB
  let y: Float32Array;
  if (kind === "clipped") y = burst(12, 150, 3.0, 0, seed).map((v) => Math.max(-1, Math.min(1, v))); // 입력이 너무 커서 깨짐
  else if (kind === "short") y = burst(2, 150, 0.3, 0, seed); // 0.36초: 너무 짧음
  else if (kind === "longlead") {
    const b = burst(12, 150, 0.3, 0, seed);
    y = new Float32Array(Math.floor(2.5 * SR) + b.length); // 앞에 2.5초 침묵
    y.set(b, Math.floor(2.5 * SR));
  } else y = burst(12, 150, 0.3, 0, seed);
  const parts = [quiet(0.4), y, quiet(0.4)];
  const out = new Float32Array(parts.reduce((s, p) => s + p.length, 0));
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.length;
  }
  if (kind === "noisy") for (let i = 0; i < out.length; i++) out[i] += 10 ** (-22 / 20) * gauss(rnd);
  return out;
}

const KINDS = [...Array(7).fill("good"), "clipped", "noisy", "short", "longlead"] as string[];
interface Row {
  kind: string;
  ok: boolean;
  rms: number;
  lead: number;
}
const rows: Row[] = [];
KINDS.forEach((kind, i) => {
  const raw = makeUtt(kind, i);
  const [snr, clip] = quality(raw);
  const y = prepWav(raw);
  const sec = y.length / SR;
  const ok = clip < 0.001 && snr >= 25 && sec >= 1.0 && sec <= 12;
  rows.push({ kind, ok, rms: 20 * Math.log10(Math.sqrt(power(y))), lead: y.findIndex((v) => Math.abs(v) > 0.01) / SR });
  console.log(`${kind}: SNR ${snr.toFixed(1)} dB · 깨진 표본 ${(clip * 100).toFixed(2)}% · 길이 ${sec.toFixed(1)}초 → ${ok ? "사용" : "버림"}`);
});
const kept = rows.filter((r) => r.ok).map((r) => r.kind);
check(
  kept.filter((k) => k === "good").length === 7 &&
    kept.includes("longlead") &&
    !["clipped", "noisy", "short"].some((k) => kept.includes(k)) &&
    rows.filter((r) => r.kind !== "clipped").every((r) => Math.abs(r.rms - TARGET_DB) < 0.1) &&
    rows.filter((r) => r.ok).every((r) => r.lead < 0.3),
  "깨진 소리 · 잡음 · 너무 짧은 녹음은 버리고, 앞 침묵은 잘라내며 음량은 -23 dB로 맞춰져야 해요.",
);

