# D40 · Part 1-3 · 글자를 소리 나는 대로: 정규화 → 토큰 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d40_text.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   숫자를 한국어 읽기로 바꾸고(한자어 · 고유어) 한글을 초성 · 중성 · 종성 토큰으로 쪼개기


import math
import re

import numpy as np

SR = 16000                                   # 표본화율 (16 kHz)
HOP = 320                                    # 20 ms마다 한 번 잼


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def frame_db(y: np.ndarray) -> np.ndarray:
    """20 ms마다 (조각 길이 40 ms) 소리 크기 dB."""
    n = (len(y) - 640) // HOP + 1
    fr = np.stack([y[i * HOP:i * HOP + 640] for i in range(n)])
    return 20 * np.log10(np.sqrt((fr ** 2).mean(1)) + 1e-9)


SINO = "영일이삼사오육칠팔구"
NATIVE = {1: "한", 2: "두", 3: "세", 4: "네", 5: "다섯", 6: "여섯", 7: "일곱", 8: "여덟", 9: "아홉"}
TENS = {1: "열", 2: "스물", 3: "서른", 4: "마흔", 5: "쉰", 6: "예순", 7: "일흔", 8: "여든", 9: "아흔"}
NATIVE_UNITS = "시|개|명|살|잔|달|번"             # 고유어(하나 둘 셋)로 읽는 단위


def read_number(n: int) -> str:
    """0 ~ 9999를 한자어로: 천 · 백 · 십 앞의 1은 읽지 않는다(123 → 백이십삼)."""
    if n == 0:
        return "영"
    out = ""
    for div, unit in ((1000, "천"), (100, "백"), (10, "십")):
        d, n = divmod(n, div)
        if d:
            out += ("" if d == 1 else SINO[d]) + unit
    return out + (SINO[n] if n else "")


def read_big(n: int) -> str:
    """만 단위 이상: 네 자리씩 끊어 읽는다(15000 → 만 오천)."""
    q, r = divmod(n, 10000)
    if q == 0:
        return read_number(r)
    return ("만" if q == 1 else read_number(q) + "만") + (" " + read_number(r) if r else "")


def read_native(n: int) -> str:
    """1 ~ 99를 고유어로(세 · 두 · 열두 · 스무)."""
    if n == 20:
        return "스무"
    t, u = divmod(n, 10)
    return (TENS[t] if t else "") + (NATIVE[u] if u else "")


def normalize_text(text: str) -> str:
    text = re.sub(rf"(\d+)({NATIVE_UNITS})", lambda m: (read_native(int(m[1])) if 0 < int(m[1]) < 100 else read_big(int(m[1]))) + " " + m[2], text)
    return re.sub(r"(\d+)([가-힣]?)", lambda m: read_big(int(m[1])) + (" " + m[2] if m[2] else ""), text)


def to_ids(text: str) -> list:
    """한글 → 초성(0~18) · 중성(19~39) · 종성(40~66) 토큰, 공백은 99. 유니코드 계산만으로 쪼갠다."""
    out = []
    for c in text:
        if "가" <= c <= "힣":
            code = ord(c) - 0xAC00
            out += [code // 588, 19 + code % 588 // 28] + ([40 + code % 28 - 1] if code % 28 else [])
        else:
            out.append(99)
    return out


def from_ids(ids: list) -> str:
    out, i = "", 0
    while i < len(ids):
        if ids[i] == 99:
            out, i = out + " ", i + 1
            continue
        code = ids[i] * 588 + (ids[i + 1] - 19) * 28
        i += 2
        if i < len(ids) and 40 <= ids[i] <= 66:
            code, i = code + ids[i] - 40 + 1, i + 1
        out += chr(0xAC00 + code)
    return out


raw = "오후 3시 30분에 2명 예약, 비용 15000원"
norm = normalize_text(raw)
print(raw, "→", norm)
ids = to_ids("한글 말해요")
print("토큰:", ids, "→ 되돌리기:", from_ids(ids))
check([read_number(n) for n in (0, 10, 11, 123, 1000, 2024, 9999)] == ["영", "십", "십일", "백이십삼", "천", "이천이십사", "구천구백구십구"]
      and [read_native(n) for n in (3, 12, 20, 21)] == ["세", "열두", "스무", "스물한"]
      and norm == "오후 세 시 삼십 분에 두 명 예약, 비용 만 오천 원" and to_ids("한글") == [18, 19, 43, 0, 37, 47] and from_ids(ids) == "한글 말해요",
      "123 → 백이십삼, 3시 → 세 시, 15000 → 만 오천, 한 → [18, 19, 43]이어야 해요.")

