// D40 · Part 1-3 · 글자를 소리 나는 대로: 정규화 → 토큰 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d40_text.ts   (소리·데이터는 코드 안에서 합성해요)
//   숫자를 한국어 읽기로 바꾸고(한자어 · 고유어) 한글을 초성 · 중성 · 종성 토큰으로 쪼개기


const SR = 16000; // 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}


const SINO = "영일이삼사오육칠팔구";
const NATIVE: Record<number, string> = { 1: "한", 2: "두", 3: "세", 4: "네", 5: "다섯", 6: "여섯", 7: "일곱", 8: "여덟", 9: "아홉" };
const TENS: Record<number, string> = { 1: "열", 2: "스물", 3: "서른", 4: "마흔", 5: "쉰", 6: "예순", 7: "일흔", 8: "여든", 9: "아흔" };
const NATIVE_UNITS = "시|개|명|살|잔|달|번"; // 고유어(하나 둘 셋)로 읽는 단위

function readNumber(n: number): string {
  // 0 ~ 9999를 한자어로: 천 · 백 · 십 앞의 1은 읽지 않는다(123 → 백이십삼)
  if (n === 0) return "영";
  let out = "";
  let rest = n;
  for (const [div, unit] of [[1000, "천"], [100, "백"], [10, "십"]] as Array<[number, string]>) {
    const d = Math.floor(rest / div);
    rest %= div;
    if (d) out += (d === 1 ? "" : SINO[d]) + unit;
  }
  return out + (rest ? SINO[rest] : "");
}

function readBig(n: number): string {
  // 만 단위 이상: 네 자리씩 끊어 읽는다(15000 → 만 오천)
  const q = Math.floor(n / 10000);
  const r = n % 10000;
  if (q === 0) return readNumber(r);
  return (q === 1 ? "만" : `${readNumber(q)}만`) + (r ? ` ${readNumber(r)}` : "");
}

function readNative(n: number): string {
  // 1 ~ 99를 고유어로(세 · 두 · 열두 · 스무)
  if (n === 20) return "스무";
  const t = Math.floor(n / 10);
  const u = n % 10;
  return (t ? TENS[t] : "") + (u ? NATIVE[u] : "");
}

function normalizeText(text: string): string {
  const a = text.replace(new RegExp(`(\\d+)(${NATIVE_UNITS})`, "g"), (_, n: string, unit: string) => `${Number(n) > 0 && Number(n) < 100 ? readNative(Number(n)) : readBig(Number(n))} ${unit}`);
  return a.replace(/(\d+)([가-힣]?)/g, (_, n: string, unit: string) => readBig(Number(n)) + (unit ? ` ${unit}` : ""));
}

function toIds(text: string): number[] {
  // 한글 → 초성(0~18) · 중성(19~39) · 종성(40~66) 토큰, 공백은 99. 유니코드 계산만으로 쪼갠다
  const out: number[] = [];
  for (const c of text) {
    if (c >= "가" && c <= "힣") {
      const code = (c.codePointAt(0) as number) - 0xac00;
      out.push(Math.floor(code / 588), 19 + Math.floor((code % 588) / 28));
      if (code % 28) out.push(40 + (code % 28) - 1);
    } else out.push(99);
  }
  return out;
}

function fromIds(ids: number[]): string {
  let out = "";
  let i = 0;
  while (i < ids.length) {
    if (ids[i] === 99) {
      out += " ";
      i++;
      continue;
    }
    let code = ids[i] * 588 + (ids[i + 1] - 19) * 28;
    i += 2;
    if (i < ids.length && ids[i] >= 40 && ids[i] <= 66) {
      code += ids[i] - 40 + 1;
      i++;
    }
    out += String.fromCodePoint(0xac00 + code);
  }
  return out;
}

const raw = "오후 3시 30분에 2명 예약, 비용 15000원";
const norm = normalizeText(raw);
console.log(raw, "→", norm);
const ids = toIds("한글 말해요");
console.log("토큰:", ids.join(", "), "→ 되돌리기:", fromIds(ids));
check(
  [0, 10, 11, 123, 1000, 2024, 9999].map(readNumber).join() === ["영", "십", "십일", "백이십삼", "천", "이천이십사", "구천구백구십구"].join() &&
    [3, 12, 20, 21].map(readNative).join() === ["세", "열두", "스무", "스물한"].join() &&
    norm === "오후 세 시 삼십 분에 두 명 예약, 비용 만 오천 원" &&
    toIds("한글").join() === [18, 19, 43, 0, 37, 47].join() &&
    fromIds(ids) === "한글 말해요",
  "123 → 백이십삼, 3시 → 세 시, 15000 → 만 오천, 한 → [18, 19, 43]이어야 해요.",
);

mas.typescript:
// D40 · Part 2 · 단조 정렬(Monotonic Alignment Search) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d40_mas.ts   (소리·데이터는 코드 안에서 합성해요)
//   뒤로 가지 않고 건너뛰지 않는 길 가운데 점수 합이 가장 큰 길로 토큰별 길이 구하기


const SR = 16000; // 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}


function mas(value: number[][]): number[][] {
  // 단조 정렬: 프레임마다 토큰 하나를 고르되, 앞 토큰으로 돌아가지도 건너뛰지도 않고(0칸 또는 1칸 전진),
  // 첫 프레임은 첫 토큰, 마지막 프레임은 마지막 토큰. 점수 합이 가장 큰 길을 0/1 표로 돌려준다
  const T = value.length;
  const N = value[0].length;
  const Q = Array.from({ length: T }, () => new Array<number>(N).fill(-1e9));
  Q[0][0] = value[0][0];
  for (let t = 1; t < T; t++) for (let j = 0; j < Math.min(t + 1, N); j++) Q[t][j] = Math.max(Q[t - 1][j], j > 0 ? Q[t - 1][j - 1] : -1e9) + value[t][j];
  const path = Array.from({ length: T }, () => new Array<number>(N).fill(0));
  let j = N - 1;
  for (let t = T - 1; t >= 0; t--) {
    path[t][j] = 1;
    if (t > 0 && j > 0 && Q[t - 1][j - 1] > Q[t - 1][j]) j--; // 이 프레임에서 토큰이 바뀌었다
  }
  return path;
}

function tokenSeconds(path: number[][], hop: number = 256, sr: number = 16000): number[] {
  // 정렬의 길에서 토큰마다의 길이(초) = 프레임 수 x hop / sr
  return path[0].map((_, j) => (path.reduce((s, row) => s + row[j], 0) * hop) / sr);
}

const ts0 = tokenSeconds([[1, 0], [1, 0], [0, 1]]);
check(Math.abs(ts0[0] - 0.032) < 1e-12 && Math.abs(ts0[1] - 0.016) < 1e-12, "토큰의 길이(초) = 프레임 수 x hop / sr");
const rnd = mulberry32(1);
const trueD = Array.from({ length: 8 }, () => 3 + Math.floor(rnd() * 6)); // 토큰 8개의 실제 길이(프레임)
const who = trueD.flatMap((d, k) => new Array<number>(d).fill(k));
const value = who.map((k) => Array.from({ length: 8 }, (_, j) => 0.5 * gauss(rnd) + (j === k ? 2 : 0))); // [대체] 텍스트 인코더 · 음향 모델 대신: 실제 토큰에 점수가 높은 합성 표
const path = mas(value);
const got = path[0].map((_, j) => path.reduce((s, row) => s + row[j], 0));
const score = path.reduce((s, row, t) => s + row.reduce((a, v, j) => a + v * value[t][j], 0), 0);
console.log(`실제 길이: [${trueD}]\n찾은 길이: [${got}] · 프레임 ${who.length}개 · 길의 점수 ${score.toFixed(1)}`);
const tokOf = path.map((row) => row.indexOf(1));
check(
  got.reduce((a, b) => a + b, 0) === who.length &&
    Math.min(...got) >= 1 &&
    path.every((row) => row.reduce((a, b) => a + b, 0) === 1) &&
    tokOf.every((k, t) => t === 0 || k - tokOf[t - 1] === 0 || k - tokOf[t - 1] === 1) &&
    tokOf[0] === 0 &&
    tokOf[tokOf.length - 1] === 7 &&
    Math.max(...got.map((g, k) => Math.abs(g - trueD[k]))) <= 1,
  "모든 프레임이 토큰 하나에 속하고, 토큰은 0 → 7 순서로 한 칸씩만 전진하고, 실제 길이와 1프레임 안에서 맞아야 해요.",
);

