# D40 · Part 2-3 · 다섯 손실 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d40_loss.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   멜 · KL · 길이 · 생성기 · 특징 일치 손실을 직접 계산하고 가중합으로 묶기


import math
import re

import numpy as np

SR = 16000                                   # 표본화율 (16 kHz)
HOP = 320                                    # 20 ms마다 한 번 잼


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def frame_db(y: np.ndarray) -> np.ndarray:
    """20 ms마다 (조각 길이 40 ms) 소리 크기 dB."""
    n = (len(y) - 640) // HOP + 1
    fr = np.stack([y[i * HOP:i * HOP + 640] for i in range(n)])
    return 20 * np.log10(np.sqrt((fr ** 2).mean(1)) + 1e-9)


W = dict(mel=35.0, kl=1.5, dur=1.0, gen=1.0, fmaps=1.0)             # 손실의 가중치(판별기 손실은 판별기 걸음에서 따로)


def mel_loss(pred, target):
    """멜 스펙트로그램 L1: 소리의 모양이 같아지게."""
    return float(np.mean(np.abs(pred - target)))


def kl_loss(m_q, logs_q, m_p, logs_p):
    """두 정규분포 N(m_q, e^logs_q)와 N(m_p, e^logs_p)의 KL: 글자에서 예측한 분포와 소리에서 구한 분포를 가깝게."""
    return float(np.mean(logs_p - logs_q - 0.5 + 0.5 * (np.exp(2 * logs_q) + (m_q - m_p) ** 2) * np.exp(-2 * logs_p)))


def dur_loss(log_d_pred, d_true):
    """길이 손실: 로그 길이의 제곱 오차."""
    return float(np.mean((log_d_pred - np.log(d_true)) ** 2))


def gen_loss(d_fake):
    """생성기(LSGAN): 가짜가 판별기에게 1(진짜)로 보이게."""
    return float(np.mean((1 - d_fake) ** 2))


def disc_loss(d_real, d_fake):
    """판별기(LSGAN): 진짜는 1, 가짜는 0으로."""
    return float(np.mean((1 - d_real) ** 2) + np.mean(d_fake ** 2))


def fmap_loss(f_real: list, f_fake: list):
    """특징 일치: 판별기 중간 층의 특징이 진짜와 가짜에서 비슷해지게."""
    return float(sum(np.mean(np.abs(a - b)) for a, b in zip(f_real, f_fake)))


rng = np.random.default_rng(0)
target = rng.normal(0, 1, (80, 50))
pred = target + 0.3 * rng.standard_normal(target.shape)
L = {"mel": mel_loss(pred, target), "kl": kl_loss(np.full(10, 0.5), np.full(10, 0.1), np.zeros(10), np.zeros(10)),
     "dur": dur_loss(np.log(np.array([4.0, 6.0, 5.0])) + 0.2, np.array([4.0, 6.0, 5.0])), "gen": gen_loss(np.array([0.3, 0.5])),
     "fmaps": fmap_loss([target[:10]], [pred[:10]])}
total = sum(W[k] * v for k, v in L.items())
for k, v in L.items():
    print(f"{k:>6}: 손실 {v:.3f} x 가중치 {W[k]:>4} = {W[k] * v:6.3f} ({W[k] * v / total:.0%})")
print(f"합계 {total:.3f} · 판별기 손실(따로) {disc_loss(np.array([0.9, 0.8]), np.array([0.3, 0.2])):.3f}")
check(mel_loss(target, target) == 0 and abs(kl_loss(np.array([1.0]), np.array([0.0]), np.array([0.0]), np.array([0.0])) - 0.5) < 1e-12
      and abs(kl_loss(np.array([0.0]), np.array([math.log(2)]), np.array([0.0]), np.array([0.0])) - 0.8069) < 1e-3
      and abs(dur_loss(np.log(np.array([2.0])) + 0.2, np.array([2.0])) - 0.04) < 1e-12 and gen_loss(np.ones(3)) == 0 and abs(disc_loss(np.ones(2), np.zeros(2))) < 1e-12
      and max(L, key=lambda k: W[k] * L[k]) == "mel", "같으면 0, KL(N(1,1)||N(0,1)) = 0.5, 가중합에서는 멜 손실이 가장 커야 해요.")

