// D40 · Part 2-3 · 다섯 손실 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d40_loss.ts   (소리·데이터는 코드 안에서 합성해요)
//   멜 · KL · 길이 · 생성기 · 특징 일치 손실을 직접 계산하고 가중합으로 묶기


const SR = 16000; // 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}


const W: Record<string, number> = { mel: 35.0, kl: 1.5, dur: 1.0, gen: 1.0, fmaps: 1.0 }; // 손실의 가중치(판별기 손실은 판별기 걸음에서 따로)
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;

function melLoss(pred: number[], target: number[]): number {
  // 멜 스펙트로그램 L1: 소리의 모양이 같아지게
  return mean(pred.map((p, i) => Math.abs(p - target[i])));
}

function klLoss(mq: number[], logsQ: number[], mp: number[], logsP: number[]): number {
  // 두 정규분포 N(m_q, e^logs_q)와 N(m_p, e^logs_p)의 KL: 글자에서 예측한 분포와 소리에서 구한 분포를 가깝게
  return mean(mq.map((_, i) => logsP[i] - logsQ[i] - 0.5 + 0.5 * (Math.exp(2 * logsQ[i]) + (mq[i] - mp[i]) ** 2) * Math.exp(-2 * logsP[i])));
}

function durLoss(logDPred: number[], dTrue: number[]): number {
  // 길이 손실: 로그 길이의 제곱 오차
  return mean(logDPred.map((p, i) => (p - Math.log(dTrue[i])) ** 2));
}

function genLoss(dFake: number[]): number {
  // 생성기(LSGAN): 가짜가 판별기에게 1(진짜)로 보이게
  return mean(dFake.map((v) => (1 - v) ** 2));
}

function discLoss(dReal: number[], dFake: number[]): number {
  // 판별기(LSGAN): 진짜는 1, 가짜는 0으로
  return mean(dReal.map((v) => (1 - v) ** 2)) + mean(dFake.map((v) => v ** 2));
}

function fmapLoss(fReal: number[][], fFake: number[][]): number {
  // 특징 일치: 판별기 중간 층의 특징이 진짜와 가짜에서 비슷해지게
  return fReal.reduce((s, a, k) => s + mean(a.map((v, i) => Math.abs(v - fFake[k][i]))), 0);
}

const rnd = mulberry32(0);
const target = Array.from({ length: 80 * 50 }, () => gauss(rnd));
const pred = target.map((v) => v + 0.3 * gauss(rnd));
const dTrue = [4, 6, 5];
const L: Record<string, number> = {
  mel: melLoss(pred, target),
  kl: klLoss(new Array(10).fill(0.5), new Array(10).fill(0.1), new Array(10).fill(0), new Array(10).fill(0)),
  dur: durLoss(dTrue.map((d) => Math.log(d) + 0.2), dTrue),
  gen: genLoss([0.3, 0.5]),
  fmaps: fmapLoss([target.slice(0, 500)], [pred.slice(0, 500)]),
};
const total = Object.entries(L).reduce((s, [k, v]) => s + W[k] * v, 0);
for (const [k, v] of Object.entries(L)) console.log(`${k}: 손실 ${v.toFixed(3)} x 가중치 ${W[k]} = ${(W[k] * v).toFixed(3)} (${((W[k] * v / total) * 100).toFixed(0)}%)`);
console.log(`합계 ${total.toFixed(3)} · 판별기 손실(따로) ${discLoss([0.9, 0.8], [0.3, 0.2]).toFixed(3)}`);
check(
  melLoss(target, target) === 0 &&
    Math.abs(klLoss([1], [0], [0], [0]) - 0.5) < 1e-12 &&
    Math.abs(klLoss([0], [Math.log(2)], [0], [0]) - 0.8069) < 1e-3 &&
    Math.abs(durLoss([Math.log(2) + 0.2], [2]) - 0.04) < 1e-12 &&
    genLoss([1, 1, 1]) === 0 &&
    Math.abs(discLoss([1, 1], [0, 0])) < 1e-12 &&
    Object.keys(L).reduce((p, q) => (W[q] * L[q] > W[p] * L[p] ? q : p)) === "mel",
  "같으면 0, KL(N(1,1)||N(0,1)) = 0.5, 가중합에서는 멜 손실이 가장 커야 해요.",
);

steps.typescript:
// D40 · Part 3 · 걸음 수와 과적합: 체크포인트 고르기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d40_steps.ts   (소리·데이터는 코드 안에서 합성해요)
//   적은 데이터로 학습하면 학습 손실은 계속 내려가도 평가 오차는 다시 올라간다: 발음 한도 안에서 가장 닮은 걸음 고르기


const SR = 16000; // 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}


// [대체] VITS 대신 장난감 '화자 파라미터' 학습. 파라미터 20개가 각자 다른 속도(lam)로 학습되고, 학습 데이터에 잡음이 섞여 있어
// 정답(모두 1) 대신 '잡음이 섞인 해'(target)를 향해 간다. 느리게 배우는 파라미터일수록 잡음 때문에 많이 틀려서 오래 학습하면 평가 오차가 다시 올라간다.
const F = 20;
const C = 0.2;
const lam = Array.from({ length: F }, (_, i) => 10 ** ((-3 * i) / (F - 1))); // 배우는 속도: 1 ~ 0.001
const target = lam.map((l, i) => 1 + (C / Math.sqrt(l)) * (i % 2 === 0 ? 1 : -1)); // 적은 데이터가 만든 잡음 섞인 해
const baseErr = lam.reduce((s, l) => s + l, 0); // 걸음 0의 평가 오차(진짜 파라미터는 모두 1)

interface Ckpt {
  step: number;
  train: number;
  cer: number;
  sim: number;
}

const rows: Ckpt[] = [];
for (let step = 0; step <= 6000; step += 300) {
  const w = target.map((t, i) => t * (1 - (1 - 0.5 * lam[i]) ** step)); // 경사하강법(학습률 0.5)을 step번 한 결과
  const dot = w.reduce((s, v) => s + v, 0);
  rows.push({
    step,
    train: w.reduce((s, v, i) => s + lam[i] * (v - target[i]) ** 2, 0),
    cer: Math.min(1, w.reduce((s, v, i) => s + lam[i] * (v - 1) ** 2, 0) / baseErr),
    sim: dot / (Math.sqrt(w.reduce((s, v) => s + v * v, 0)) * Math.sqrt(F) + 1e-12),
  });
}

function pickBest(rs: Ckpt[], maxCer: number): number | null {
  // 발음 오류(cer)가 한도 이하인 체크포인트 가운데 화자 유사도가 가장 높은 걸음. 없으면 null
  const ok = rs.filter((r) => r.cer <= maxCer);
  return ok.length ? ok.reduce((p, q) => (q.sim > p.sim ? q : p)).step : null;
}

rows.forEach((r, i) => {
  if (i % 2 === 0) console.log(`걸음 ${r.step}: 학습 손실 ${r.train.toFixed(3)} · 발음 오류(대용) ${r.cer.toFixed(3)} · 화자 유사도 ${r.sim.toFixed(3)}`);
});
const MAX_CER = 1.1 * Math.min(...rows.map((r) => r.cer));
const best = pickBest(rows, MAX_CER);
const last = rows[rows.length - 1];
const minRow = rows.reduce((p, q) => (q.cer < p.cer ? q : p));
console.log(`발음 한도 ${MAX_CER.toFixed(3)} → 고른 걸음 ${best} (마지막 ${last.step})`);
check(
  rows.every((a, i) => i === 0 || rows[i - 1].train >= a.train - 1e-9) &&
    minRow.step !== 0 &&
    minRow.step !== last.step &&
    last.cer > MAX_CER &&
    best !== null &&
    best > 0 &&
    best < last.step &&
    pickBest([{ step: 1, train: 0, cer: 0.2, sim: 0.9 }, { step: 2, train: 0, cer: 0.05, sim: 0.7 }], 0.1) === 2 &&
    pickBest([{ step: 1, train: 0, cer: 0.5, sim: 0.9 }], 0.1) === null,
  "학습 손실은 계속 내려가지만 평가 오차는 중간에서 가장 낮고 다시 올라가요. 발음 한도 안에서 가장 닮은 걸음을 골라야 해요.",
);

