// D40 · Part 4-2 · 워터마크: 합성음임을 표시하기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d40_wm.ts   (소리·데이터는 코드 안에서 합성해요)
//   열쇠로 만든 ±1 수열을 작게 더하고 상관 점수(z)로 검출 · 어디까지 견디나 시험


const SR = 16000; // 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}


function burst(nSyl: number, f0: number, amp: number = 0.3, jitter: number = 0, seed: number = 0): Float32Array {
  // [대체] TTS 대신 합성 목소리: 음절 nSyl개(0.18초, 앞 85%가 소리). jitter는 높낮이가 떨리는 정도, 음절마다 배음 2개
  const rnd = mulberry32(seed);
  const L = Math.floor(0.18 * SR);
  const m = Math.floor(L * 0.85);
  const y = new Float32Array(nSyl * L);
  for (let i = 0; i < nSyl; i++) {
    const f = f0 * (1 + jitter * gauss(rnd));
    for (let j = 0; j < m; j++) {
      const s = Math.sin((2 * Math.PI * f * j) / SR) + 0.4 * Math.sin((2 * Math.PI * 2 * f * j) / SR);
      y[i * L + j] = ((amp * s) / 1.4) * (0.5 - 0.5 * Math.cos((2 * Math.PI * j) / (m - 1)));
    }
  }
  return y;
}


function keySeq(key: number, n: number): Float32Array {
  // 열쇠(key)로 만든 +1 / -1 수열: 열쇠를 아는 사람만 같은 수열을 만들 수 있다
  const r = mulberry32(key);
  return Float32Array.from({ length: n }, () => (r() < 0.5 ? -1 : 1));
}

function wmScore(y: Float32Array, key: number): number {
  // 열쇠 수열과의 상관을 표준화한 z 점수: 표시가 없으면 평균 0, 표준편차 1 근처
  const w = keySeq(key, y.length);
  let dot = 0;
  let s = 0;
  let s2 = 0;
  for (let i = 0; i < y.length; i++) {
    dot += y[i] * w[i];
    s += y[i];
    s2 += y[i] * y[i];
  }
  const mean = s / y.length;
  return dot / (Math.sqrt(s2 / y.length - mean * mean) * Math.sqrt(y.length));
}

function addWatermark(y: Float32Array, key: number, db: number = -26.0): Float32Array {
  // 말 크기(RMS)보다 db만큼 작은 열쇠 수열을 더한다
  const a = 10 ** (db / 20) * Math.sqrt(power(y));
  const w = keySeq(key, y.length);
  return y.map((v, i) => v + a * w[i]);
}

function detect(y: Float32Array, key: number, th: number = 4.0): [number, boolean] {
  const z = wmScore(y, key);
  return [z, z > th];
}

const KEY = 1234;
const rnd = mulberry32(0);
const speech = burst(25, 140, 0.3, 0.01, 1);
const clean = speech.map((v) => v + 0.001 * gauss(rnd));
const marked = addWatermark(clean, KEY);
const noiseGain = 10 ** (-20 / 20) * Math.sqrt(power(marked));
const lowpass = marked.map((v, i) => (i === 0 ? v : (v + marked[i - 1]) / 2));
const n2 = Math.ceil((marked.length - 1) / 1.1);
const sped = Float32Array.from({ length: n2 }, (_, i) => {
  const x = i * 1.1;
  const k = Math.floor(x);
  return marked[k] + (marked[Math.min(k + 1, marked.length - 1)] - marked[k]) * (x - k);
});
const tests: Record<string, [number, boolean]> = {
  "표시 없음": detect(clean, KEY),
  "표시 있음": detect(marked, KEY),
  "다른 열쇠로 검사": detect(marked, KEY + 1),
  "잡음 20 dB 추가": detect(marked.map((v) => v + noiseGain * gauss(rnd)), KEY),
  "저역 통과(2개 평균)": detect(lowpass, KEY),
  "속도 1.1배": detect(sped, KEY),
};
for (const [name, [z, hit]] of Object.entries(tests)) console.log(`${name} z = ${z.toFixed(1)} → ${hit ? "표시 검출" : "검출 안 됨"}`);
const snrWm = 10 * Math.log10(power(clean) / power(marked.map((v, i) => v - clean[i])));
console.log(`더한 표시의 크기: 말 대비 ${snrWm.toFixed(0)} dB`);
check(
  !tests["표시 없음"][1] && tests["표시 있음"][1] && !tests["다른 열쇠로 검사"][1] && tests["잡음 20 dB 추가"][1] && tests["저역 통과(2개 평균)"][1] && !tests["속도 1.1배"][1] && Math.abs(snrWm - 26) < 1,
  "열쇠가 맞고 표시가 있을 때만 검출돼요. 잡음 · 저역 통과는 견디지만 속도를 바꾸면 못 찾는다는 한계도 기억하세요.",
);

