# D40 · Part 5 · 정리: 핵심 공식 다시 확인 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d40_recap.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   숫자 읽기 · 단조 정렬 · KL · 손실 가중합 · 워터마크 점수 공식을 작은 함수로 확인


import math
import re

import numpy as np

SR = 16000                                   # 표본화율 (16 kHz)
HOP = 320                                    # 20 ms마다 한 번 잼


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def frame_db(y: np.ndarray) -> np.ndarray:
    """20 ms마다 (조각 길이 40 ms) 소리 크기 dB."""
    n = (len(y) - 640) // HOP + 1
    fr = np.stack([y[i * HOP:i * HOP + 640] for i in range(n)])
    return 20 * np.log10(np.sqrt((fr ** 2).mean(1)) + 1e-9)


import math


def read_number(n):
    if n == 0:
        return "영"
    s, out = "영일이삼사오육칠팔구", ""
    for div, unit in ((1000, "천"), (100, "백"), (10, "십")):
        d, n = divmod(n, div)
        if d:
            out += ("" if d == 1 else s[d]) + unit
    return out + (s[n] if n else "")


def kl_unit_variance(mean_diff):
    return mean_diff ** 2 / 2


def weighted_loss(losses, weights):
    return sum(weights[k] * v for k, v in losses.items())


def wm_z(correlation_sum, std, n):
    return correlation_sum / (std * math.sqrt(n))


quiz = {
    "123 → 백이십삼": read_number(123) == "백이십삼",
    "2024 → 이천이십사": read_number(2024) == "이천이십사",
    "분산이 같을 때 KL = (평균 차이)² / 2": kl_unit_variance(1.0) == 0.5 and kl_unit_variance(2.0) == 2.0,
    "손실 가중합 = 35 x 0.1 + 1.5 x 0.2": abs(weighted_loss({"mel": 0.1, "kl": 0.2}, {"mel": 35.0, "kl": 1.5}) - 3.8) < 1e-9,
    "워터마크 z = 합 / (표준편차 x 루트 N)": abs(wm_z(40.0, 1.0, 100) - 4.0) < 1e-12,
}
for q, ok in quiz.items():
    print(("O " if ok else "X ") + q)
check(all(quiz.values()), "틀린 항목(X)을 위 줄에서 찾아 공식을 다시 확인하세요.")

